// Create a logo in the top-left corner
ScreenImageMgr.createScreenImage("logo", "logo.png", 10, 10, 1.0, true, 1.0);

// Create a semi-transparent watermark in the bottom-right corner
var screenWidth = core.getScreenWidth();
var screenHeight = core.getScreenHeight();
ScreenImageMgr.createScreenImage("watermark", "watermark.png", screenWidth - 200, screenHeight - 100, 0.8, true, 0.5, 2.0);

// Create an invisible image that will fade in later
ScreenImageMgr.createScreenImage("hidden", "overlay.png", 100, 100, 1.0, false, 1.0);

// Later, show it
ScreenImageMgr.showImage("hidden", true);

if(ScreenImageMgr.getShowImage("logo")) {
    core.debug("Logo is visible");
} else {
    core.debug("Logo is hidden");
    ScreenImageMgr.showImage("logo", true);
}

// Hide the logo
ScreenImageMgr.showImage("logo", false);

// Wait 2 seconds, then show it again
core.wait(2);
ScreenImageMgr.showImage("logo", true);

// Create a sequence of image appearances
var images = ["img1", "img2", "img3"];
for(var i=0; i<images.length; i++) {
    ScreenImageMgr.createScreenImage(images[i], images[i] + ".png", 100, 100);
    ScreenImageMgr.showImage(images[i], false);
}
for(var i=0; i<images.length; i++) {
    core.wait(1);
    ScreenImageMgr.showImage(images[i], true);
}

var width = ScreenImageMgr.getImageWidth("logo");
core.debug("Logo width: " + width + " pixels");

// Center an image on screen
var screenW = core.getScreenWidth();
var screenH = core.getScreenHeight();
var imgW = ScreenImageMgr.getImageWidth("logo");
var imgH = ScreenImageMgr.getImageHeight("logo");
ScreenImageMgr.setImageXY("logo", (screenW - imgW) / 2, (screenH - imgH) / 2);

// Zoom in slowly over 2 seconds
ScreenImageMgr.setImageScale("logo", 2.0, 2.0, 2.0);

// Shrink instantly
ScreenImageMgr.setImageScale("logo", 0.5, 0.5, 0);

// Stretch horizontally only
ScreenImageMgr.setImageScale("logo", 3.0, 1.0, 1.5);

// Create a pulsing effect
for(var i=0; i<3; i++) {
    ScreenImageMgr.setImageScale("logo", 1.2, 1.2, 0.5);
    core.wait(0.5);
    ScreenImageMgr.setImageScale("logo", 1.0, 1.0, 0.5);
    core.wait(0.5);
}

// Make the logo semi-transparent
ScreenImageMgr.setImageAlpha("logo", 0.6);

// Make it fully opaque
ScreenImageMgr.setImageAlpha("logo", 1.0);

// Create a fade-out effect by reducing alpha over time
ScreenImageMgr.setImageAlpha("logo", 0.8);
core.wait(1);
ScreenImageMgr.setImageAlpha("logo", 0.5);
core.wait(1);
ScreenImageMgr.setImageAlpha("logo", 0.2);
core.wait(1);
ScreenImageMgr.showImage("logo", false);

// Move logo to top-right corner instantly
var screenW = core.getScreenWidth();
var imgW = ScreenImageMgr.getImageWidth("logo");
ScreenImageMgr.setImageXY("logo", screenW - imgW - 10, 10, 0);

// Move logo across the screen slowly (slide-in effect)
ScreenImageMgr.setImageXY("logo", 10, 100, 2.0);

// Move to center of screen
ScreenImageMgr.setImageXY("logo", (screenW - imgW) / 2, (screenH - imgH) / 2, 1.5);

// Move logo 100 pixels right and 50 pixels down
ScreenImageMgr.addImageXY("logo", 100, 50, 1.0);

// Create a bouncing effect
for(var i = 0; i < 3; i++) {
    ScreenImageMgr.addImageXY("logo", 0, -20, 0.3);
    core.wait(0.3);
    ScreenImageMgr.addImageXY("logo", 0, 20, 0.3);
    core.wait(0.3);
}

// Create a wavy motion path
for(var i = 0; i < 10; i++) {
    ScreenImageMgr.addImageXY("logo", 20, 0, 0.2);
    ScreenImageMgr.addImageXY("logo", 0, 10, 0.2);
}

// Delete a specific image
ScreenImageMgr.deleteImage("logo");

// Check if image exists before deleting
var allImages = ScreenImageMgr.getAllImageIDs();
if(allImages.indexOf("logo") >= 0) {
    ScreenImageMgr.deleteImage("logo");
    core.debug("Logo deleted");
}

// Clean up all images at the end of a presentation
ScreenImageMgr.deleteAllImages();
core.debug("All images cleared");

// Count images before and after
var count = ScreenImageMgr.getAllImageIDs().length;
core.debug("Images before: " + count);
ScreenImageMgr.deleteAllImages();
core.debug("Images after: 0");

var allImages = ScreenImageMgr.getAllImageIDs();
core.debug("Total images: " + allImages.length);

// Print all image IDs
for(var i=0; i<allImages.length; i++) {
    core.debug((i+1) + ". " + allImages[i]);
}

// Hide all images
var images = ScreenImageMgr.getAllImageIDs();
for(var i=0; i<images.length; i++) {
    ScreenImageMgr.showImage(images[i], false);
}

// Check if a specific image exists
function imageExists(id) {
    return ScreenImageMgr.getAllImageIDs().indexOf(id) >= 0;
}

if(imageExists("logo")) {
    core.debug("Logo exists");
}
